'use strict';
const path = require('path');
const fs = require('fs-extra');
const unzipper = require('unzipper');
const os = require('os');

/**
 * Extract a ZIP file to a temporary directory.
 *
 * @param {string} zipPath  – path to the uploaded .zip file
 * @param {string} buildId
 * @returns {string} extractedDir
 */
async function extract(zipPath, buildId) {
  const destDir = path.join(os.tmpdir(), `apkbuilder-zip-${buildId}`);
  await fs.ensureDir(destDir);

  await new Promise((resolve, reject) => {
    fs.createReadStream(zipPath)
      .pipe(unzipper.Extract({ path: destDir }))
      .on('close', resolve)
      .on('error', reject);
  });

  // If the ZIP extracted into a single subfolder (common pattern),
  // return that subfolder as the web root.
  const entries = await fs.readdir(destDir, { withFileTypes: true });
  const nonHidden = entries.filter(e => !e.name.startsWith('.'));

  if (nonHidden.length === 1 && nonHidden[0].isDirectory()) {
    const subDir = path.join(destDir, nonHidden[0].name);
    // Check if index.html lives in sub-directory
    if (await fs.pathExists(path.join(subDir, 'index.html'))) {
      return subDir;
    }
  }

  return destDir;
}

module.exports = { extract };
